import glob, yaml, random, os
rows=[]
for p in sorted(glob.glob('tmp/review-triages/*.yaml')+glob.glob('docs/review-triage/*.yaml')):
    try: d=yaml.safe_load(open(p))
    except Exception: continue
    for ri,run in enumerate((d or {}).get('runs') or [],1):
        for f in run.get('findings') or []:
            if f.get('verdict')=='adopted' and isinstance(f.get('consequence'),dict):
                rows.append((os.path.basename(p)[:-5],ri,f))
random.seed(178)
for i,(rec,ri,f) in enumerate(random.sample(rows,20),1):
    c=f['consequence']; t=lambda s:str(s or '').replace('\n',' ')[:150]
    print(f"[{i}] {rec[:34]} r{ri} {str(f.get('file'))[-38:]} sev={(f.get('attrs') or {}).get('severity')} aud={f.get('audience')}")
    print('  要旨:',t(f.get('summary')))
    print('  誰に:',t(c.get('who')),'| 何が:',t(c.get('what')))
    print('  気づけるか:',t(c.get('detectability')))
EOF

